/* output.c - naming, the "generated by niu" header, and writing lowered
 * files next to their originals (spec.md "Output"). Part of niu.c; not
 * compiled on its own. */

/* The first line of every file niu writes starts with this. niu replaces an
 * existing file only when it starts with it too. */
#define NIU_GENERATED_PREFIX "/* Generated by niu"

static const char niu_utf8_bom[] = "\xEF\xBB\xBF";

/* x.niu.c -> x.c, x.niu.h -> x.h, anything else gets ".plain" before its
 * extension: x.c -> x.plain.c, x -> x.plain. */
static char *niu_output_name(const char *input)
{
    const char *base = niu_basename(input);
    const char *dot = strrchr(base, '.');
    size_t n = strlen(input);
    if (niu_ends_with(base, ".niu.c") || niu_ends_with(base, ".niu.h")) {
        /* drop ".niu", keep ".c"/".h" */
        return niu_format("%.*s%s", (int)(n - 6), input, input + n - 2);
    }
    if (!dot || dot == base)
        return niu_format("%s.plain", input);
    return niu_format("%.*s.plain%s", (int)(dot - input), input, dot);
}

/* Named like a niu file (only the name decides the output name). */
static int niu_has_niu_name(const char *input)
{
    const char *base = niu_basename(input);
    return niu_ends_with(base, ".niu.c") || niu_ends_with(base, ".niu.h");
}

/* An existing file that niu wrote itself? */
static int niu_is_generated(const char *path)
{
    char head[64];
    size_t n = niu_read_prefix(path, head, sizeof head);
    const char *p = head;
    size_t plen = strlen(NIU_GENERATED_PREFIX);
    if (n >= 3 && memcmp(head, niu_utf8_bom, 3) == 0) {
        p += 3;
        n -= 3;
    }
    return n >= plen && memcmp(p, NIU_GENERATED_PREFIX, plen) == 0;
}

/* The line ending the file uses: that of its first line, "\n" when it has
 * none. Lines niu adds use it too, so CRLF files stay CRLF. */
static const char *niu_line_ending(const char *src, size_t len)
{
    const char *nl = (const char *)memchr(src, '\n', len);
    if (nl && nl > src && nl[-1] == '\r')
        return "\r\n";
    return "\n";
}

/* Appends s as the inside of a C string literal. */
static void niu_append_string_literal(niu_buf *out, const char *s)
{
    for (; *s; s++) {
        if (*s == '\\' || *s == '"')
            niu_buf_putc(out, '\\');
        niu_buf_putc(out, *s);
    }
}

/* Builds the lowered file: the generated comment, #line (unless no_line),
 * then the original text with the edits applied. */
static int niu_render_output(const char *input, const char *src, size_t len, niu_edits *edits, int no_line,
                             niu_buf *out)
{
    const char *eol = niu_line_ending(src, len);
    const char *name = niu_basename(input);
    /* A byte order mark has to stay the very first thing in the file. */
    if (len >= 3 && memcmp(src, niu_utf8_bom, 3) == 0) {
        niu_buf_append(out, src, 3);
        niu_edits_add(edits, 0, 3, niu_strdup(""));
    }
    niu_buf_puts(out, NIU_GENERATED_PREFIX " from \"");
    niu_append_comment_safe(out, name, strlen(name));
    niu_buf_printf(out, "\". Edit that file instead. */%s", eol);
    if (!no_line) {
        niu_buf_puts(out, "#line 1 \"");
        niu_append_string_literal(out, name);
        niu_buf_printf(out, "\"%s", eol);
    }
    return niu_edits_apply(edits, src, len, out);
}

/* Writes the lowered text to output, refusing to replace a file that niu did
 * not generate. */
static int niu_write_output(const char *input, const char *output, const niu_buf *text)
{
    char *tmp;
    FILE *f;
    int ok;
    if (niu_exists(output) && (!niu_is_file(output) || !niu_is_generated(output))) {
        niu_message_at(input, "error", "cannot write '%s': the file exists and was not generated by niu", output);
        return 0;
    }
    /* Write next to the target and move it into place, so that a failed
     * write never leaves a half-written output behind. */
    tmp = niu_format("%s.niu-tmp", output);
    f = fopen(tmp, "wb");
    if (!f) {
        niu_message_at(input, "error", "cannot write '%s': %s", tmp, strerror(errno));
        free(tmp);
        return 0;
    }
    ok = fwrite(text->data, 1, text->len, f) == text->len;
    ok = (fclose(f) == 0) && ok;
    if (!ok) {
        niu_message_at(input, "error", "cannot write '%s': %s", tmp, strerror(errno));
        remove(tmp);
        free(tmp);
        return 0;
    }
    if (!niu_replace_file(tmp, output)) {
        niu_message_at(input, "error", "cannot replace '%s'", output);
        remove(tmp);
        free(tmp);
        return 0;
    }
    free(tmp);
    return 1;
}
